  // Technique detail info
  'techniques.box.detail': 'Navy SEALs \u0926\u094D\u0935\u093E\u0930\u093E \u0924\u0928\u093E\u0935 \u092A\u094D\u0930\u092C\u0902\u0927\u0928 \u0915\u0947 \u0932\u093F\u090F \u0909\u092A\u092F\u094B\u0917 \u0915\u093F\u092F\u093E \u091C\u093E\u0924\u093E \u0939\u0948\u0964 \u0938\u092E\u093E\u0928 \u0936\u094D\u0935\u093E\u0938, \u0930\u094B\u0915, \u0928\u093F\u0903\u0936\u094D\u0935\u093E\u0938 \u0914\u0930 \u0930\u094B\u0915 \u091A\u0930\u0923 \u090F\u0915 \u0936\u093E\u0902\u0924 \u0932\u092F \u092C\u0928\u093E\u0924\u0947 \u0939\u0948\u0902 \u091C\u094B \u0915\u094B\u0930\u094D\u091F\u093F\u0938\u094B\u0932 \u0915\u092E \u0915\u0930\u0924\u093E \u0939\u0948 \u0914\u0930 \u092B\u094B\u0915\u0938 \u092C\u0922\u093C\u093E\u0924\u093E \u0939\u0948\u0964',
  'techniques.fourSevenEight.detail': '\u0921\u0949. \u090F\u0902\u0921\u094D\u0930\u0942 \u0935\u0947\u0932 \u0926\u094D\u0935\u093E\u0930\u093E \u0935\u093F\u0915\u0938\u093F\u0924\u0964 \u0932\u0902\u092C\u0940 \u0928\u093F\u0903\u0936\u094D\u0935\u093E\u0938 \u092A\u0948\u0930\u093E\u0938\u093F\u092E\u094D\u092A\u0947\u0925\u0947\u091F\u093F\u0915 \u0924\u0902\u0924\u094D\u0930\u093F\u0915\u093E \u0924\u0902\u0924\u094D\u0930 \u0915\u094B \u0938\u0915\u094D\u0930\u093F\u092F \u0915\u0930\u0924\u0940 \u0939\u0948, \u091C\u093F\u0938\u0938\u0947 \u092E\u093F\u0928\u091F\u094B\u0902 \u092E\u0947\u0902 \u0928\u0940\u0902\u0926 \u0906\u0928\u0947 \u092E\u0947\u0902 \u092E\u0926\u0926 \u092E\u093F\u0932\u0924\u0940 \u0939\u0948\u0964',
  'techniques.physioSigh.detail': 'Stanford \u0928\u094D\u092F\u0942\u0930\u094B\u0938\u093E\u0907\u0902\u091F\u093F\u0938\u094D\u091F \u0921\u0949. \u090F\u0902\u0921\u094D\u0930\u0942 \u0939\u0941\u092C\u0930\u092E\u0948\u0928 \u0926\u094D\u0935\u093E\u0930\u093E \u0916\u094B\u091C\u093E \u0917\u092F\u093E\u0964 \u0926\u094B\u0939\u0930\u0940 \u0936\u094D\u0935\u093E\u0938 \u0915\u0947 \u092C\u093E\u0926 \u0932\u0902\u092C\u0940 \u0928\u093F\u0903\u0936\u094D\u0935\u093E\u0938 \u0924\u0928\u093E\u0935 \u0915\u092E \u0915\u0930\u0928\u0947 \u0915\u093E \u0938\u092C\u0938\u0947 \u0924\u0947\u091C\u093C \u0924\u0930\u0940\u0915\u093E \u0939\u0948\u0964',
  'techniques.coherence.detail': '\u092A\u094D\u0930\u0924\u093F \u092E\u093F\u0928\u091F 5.5 \u0938\u093E\u0901\u0938 \u0932\u0947\u0928\u0947 \u0938\u0947 \u0939\u0943\u0926\u092F \u0917\u0924\u093F, \u0930\u0915\u094D\u0924\u091A\u093E\u092A \u0914\u0930 \u0924\u0902\u0924\u094D\u0930\u093F\u0915\u093E \u0924\u0902\u0924\u094D\u0930 \u0938\u092E\u0928\u094D\u0935\u093F\u0924 \u0939\u094B\u0924\u093E \u0939\u0948 \u2014 \u0907\u0937\u094D\u091F\u0924\u092E HRV \u0915\u0947 \u0932\u093F\u090F "\u0915\u094B\u0939\u0947\u0930\u0947\u0902\u0938" \u0915\u0940 \u0938\u094D\u0925\u093F\u0924\u093F \u092A\u094D\u0930\u093E\u092A\u094D\u0924 \u0939\u094B\u0924\u0940 \u0939\u0948\u0964',
  'techniques.triangle.detail': '\u0936\u0941\u0930\u0941\u0906\u0924\u0940 \u0932\u094B\u0917\u094B\u0902 \u0915\u0947 \u0932\u093F\u090F \u090F\u0915 \u0938\u0930\u0932 3-\u091A\u0930\u0923 \u092A\u0948\u091F\u0930\u094D\u0928\u0964 \u0938\u093E\u0901\u0938 \u0930\u094B\u0915\u0947 \u092C\u093F\u0928\u093E \u0924\u0902\u0924\u094D\u0930\u093F\u0915\u093E \u0924\u0902\u0924\u094D\u0930 \u0915\u094B \u0938\u0902\u0924\u0941\u0932\u093F\u0924 \u0915\u0930\u0924\u093E \u0939\u0948, \u091C\u093F\u0938\u0938\u0947 \u092F\u0939 \u0938\u092C\u0915\u0947 \u0932\u093F\u090F \u0906\u0938\u093E\u0928 \u0914\u0930 \u0938\u0941\u0932\u092D \u0939\u0948\u0964',
  'techniques.power.detail': '\u0935\u093F\u092E \u0939\u0949\u092B \u092E\u0947\u0925\u0921 \u0938\u0947 \u092A\u094D\u0930\u0947\u0930\u093F\u0924\u0964 \u0924\u0947\u091C\u093C \u0938\u093E\u0901\u0938 \u0915\u0947 \u092C\u093E\u0926 \u0938\u093E\u0901\u0938 \u0930\u094B\u0915\u0928\u093E \u090A\u0930\u094D\u091C\u093E \u092C\u0922\u093C\u093E\u0924\u093E \u0939\u0948, \u0930\u0915\u094D\u0924 \u0915\u094B \u0915\u094D\u0937\u093E\u0930\u0940\u092F \u092C\u0928\u093E\u0924\u093E \u0939\u0948 \u0914\u0930 \u092A\u094D\u0930\u0924\u093F\u0930\u0915\u094D\u0937\u093E \u092A\u094D\u0930\u0924\u093F\u0915\u094D\u0930\u093F\u092F\u093E \u0915\u094B \u092C\u0922\u093C\u093E\u0924\u093E \u0939\u0948\u0964',
  'techniques.fourFourSixTwo.detail': '\u0932\u0902\u092C\u0940 \u0928\u093F\u0903\u0936\u094D\u0935\u093E\u0938 (6\u0938\u0947) \u0936\u094D\u0935\u093E\u0938 (4\u0938\u0947) \u0915\u0940 \u0924\u0941\u0932\u0928\u093E \u092E\u0947\u0902 \u0936\u0930\u0940\u0930 \u0915\u094B \u0917\u0939\u0930\u0947 \u0935\u093F\u0936\u094D\u0930\u093E\u092E \u092E\u0947\u0902 \u0932\u0947 \u091C\u093E\u0924\u0940 \u0939\u0948\u0964 \u091A\u0915\u094D\u0930\u094B\u0902 \u0915\u0947 \u092C\u0940\u091A \u091B\u094B\u091F\u093E \u0935\u093F\u0930\u093E\u092E \u0938\u093E\u0901\u0938 \u0915\u0940 \u0932\u092F \u0915\u094B \u0930\u0940\u0938\u0947\u091F \u0915\u0930\u0924\u093E \u0939\u0948\u0964',
  'techniques.kapalabhati.detail': '\u092A\u094D\u0930\u093E\u091A\u0940\u0928 \u092F\u094B\u0917\u093F\u0915 \u0924\u0915\u0928\u0940\u0915 \u091C\u093F\u0938\u0915\u093E \u0905\u0930\u094D\u0925 \u0939\u0948 "\u0916\u094B\u092A\u0921\u093C\u0940 \u091A\u092E\u0915\u093E\u0928\u0947 \u0935\u093E\u0932\u0940 \u0938\u093E\u0901\u0938\u0964" \u0924\u0947\u091C\u093C \u091C\u094B\u0930\u0926\u093E\u0930 \u0928\u093F\u0903\u0936\u094D\u0935\u093E\u0938 \u0936\u0930\u0940\u0930 \u0915\u094B \u090A\u0930\u094D\u091C\u093E\u0935\u093E\u0928 \u0915\u0930\u0924\u0940 \u0939\u0948, \u092E\u0928 \u0938\u093E\u092B\u093C \u0915\u0930\u0924\u0940 \u0939\u0948 \u0914\u0930 \u0921\u093E\u092F\u092B\u094D\u0930\u093E\u092E \u0915\u094B \u092E\u091C\u093C\u092C\u0942\u0924 \u0915\u0930\u0924\u0940 \u0939\u0948\u0964',
  'techniques.twoToOne.detail': '\u0928\u093F\u0903\u0936\u094D\u0935\u093E\u0938 \u0936\u094D\u0935\u093E\u0938 \u0915\u0940 \u0926\u094B\u0917\u0941\u0928\u0940 \u0932\u0902\u092C\u093E\u0908 \u0915\u0940 \u0939\u094B\u0924\u0940 \u0939\u0948, \u091C\u094B CO\u2082 \u0930\u093F\u0932\u0940\u091C\u093C \u0915\u094B \u0905\u0927\u093F\u0915\u0924\u092E \u0915\u0930\u0924\u0940 \u0939\u0948 \u0914\u0930 \u0935\u0947\u0917\u0938 \u0928\u0930\u094D\u0935 \u0915\u094B \u0938\u0915\u094D\u0930\u093F\u092F \u0915\u0930\u0924\u0940 \u0939\u0948\u0964 \u0917\u0939\u0930\u0947 \u0935\u093F\u0936\u094D\u0930\u093E\u092E \u0915\u0947 \u0932\u093F\u090F \u0938\u092C\u0938\u0947 \u092A\u094D\u0930\u092D\u093E\u0935\u0936\u093E\u0932\u0940 \u092A\u0948\u091F\u0930\u094D\u0928 \u092E\u0947\u0902 \u0938\u0947 \u090F\u0915\u0964',
