  // Motivational quotes
  'summary.quote1': '"\u0938\u093E\u0901\u0938 \u0935\u0939 \u0938\u0947\u0924\u0941 \u0939\u0948 \u091C\u094B \u091C\u0940\u0935\u0928 \u0915\u094B \u091A\u0947\u0924\u0928\u093E \u0938\u0947 \u091C\u094B\u0921\u093C\u0924\u0940 \u0939\u0948\u0964" \u2014 \u0925\u093F\u091A \u0928\u094D\u0939\u093E\u0924 \u0939\u093E\u0928\u094D\u0939',
  'summary.quote2': '"\u092D\u093E\u0935\u0928\u093E\u090F\u0901 \u0924\u0942\u092B\u093E\u0928\u0940 \u0906\u0915\u093E\u0936 \u092E\u0947\u0902 \u092C\u093E\u0926\u0932\u094B\u0902 \u0915\u0940 \u0924\u0930\u0939 \u0906\u0924\u0940-\u091C\u093E\u0924\u0940 \u0939\u0948\u0902\u0964 \u0938\u091A\u0947\u0924 \u0938\u093E\u0901\u0938 \u092E\u0947\u0930\u093E \u0932\u0902\u0917\u0930 \u0939\u0948\u0964" \u2014 \u0925\u093F\u091A \u0928\u094D\u0939\u093E\u0924 \u0939\u093E\u0928\u094D\u0939',
  'summary.quote3': '"\u092E\u0928 \u0907\u0902\u0926\u094D\u0930\u093F\u092F\u094B\u0902 \u0915\u093E \u0930\u093E\u091C\u093E \u0939\u0948, \u0932\u0947\u0915\u093F\u0928 \u0938\u093E\u0901\u0938 \u092E\u0928 \u0915\u093E \u0930\u093E\u091C\u093E \u0939\u0948\u0964" \u2014 \u0939\u0920 \u092F\u094B\u0917 \u092A\u094D\u0930\u0926\u0940\u092A\u093F\u0915\u093E',
  'summary.quote4': '"\u091C\u092C \u0906\u092A \u0905\u092A\u0928\u0940 \u0938\u093E\u0901\u0938 \u092A\u0930 \u0928\u093F\u092F\u0902\u0924\u094D\u0930\u0923 \u0930\u0916\u0924\u0947 \u0939\u0948\u0902, \u0924\u094B \u0915\u094B\u0908 \u0906\u092A\u0915\u0940 \u0936\u093E\u0902\u0924\u093F \u0928\u0939\u0940\u0902 \u091B\u0940\u0928 \u0938\u0915\u0924\u093E\u0964"',
  'summary.quote5': '"\u0936\u093E\u0902\u0924\u093F \u0936\u094D\u0935\u093E\u0938 \u092E\u0947\u0902 \u0932\u0947\u0902, \u0924\u0928\u093E\u0935 \u0928\u093F\u0903\u0936\u094D\u0935\u093E\u0938 \u092E\u0947\u0902 \u091B\u094B\u0921\u093C\u0947\u0902\u0964"',
  'summary.quote6': '"\u0935\u0930\u094D\u0924\u092E\u093E\u0928 \u0915\u094D\u0937\u0923 \u0906\u0928\u0902\u0926 \u0914\u0930 \u0938\u0941\u0916 \u0938\u0947 \u092D\u0930\u093E \u0939\u0948\u0964 \u092F\u0926\u093F \u0906\u092A \u0938\u091A\u0947\u0924 \u0939\u0948\u0902, \u0924\u094B \u0906\u092A \u0907\u0938\u0947 \u0926\u0947\u0916\u0947\u0902\u0917\u0947\u0964" \u2014 \u0925\u093F\u091A \u0928\u094D\u0939\u093E\u0924 \u0939\u093E\u0928\u094D\u0939',
  'summary.quote7': '"\u092D\u0935\u093F\u0937\u094D\u092F \u0915\u094B \u0936\u094D\u0935\u093E\u0938 \u092E\u0947\u0902 \u0932\u0947\u0902, \u0905\u0924\u0940\u0924 \u0915\u094B \u0928\u093F\u0903\u0936\u094D\u0935\u093E\u0938 \u092E\u0947\u0902 \u091B\u094B\u0921\u093C\u0947\u0902\u0964"',
  'summary.quote8': '"\u092C\u0938 \u0938\u093E\u0901\u0938 \u0932\u094B\u0964 \u0906\u092A \u092A\u0930\u094D\u092F\u093E\u092A\u094D\u0924 \u0939\u0948\u0902\u0964"',
  'summary.quote9': '"\u0936\u093E\u0902\u0924\u093F \u090F\u0915 \u0938\u093E\u0901\u0938 \u0938\u0947 \u0936\u0941\u0930\u0942 \u0939\u094B\u0924\u0940 \u0939\u0948\u0964"',
  'summary.quote10': '"\u0906\u092A\u0915\u0940 \u0938\u093E\u0901\u0938 \u0906\u0924\u094D\u092E-\u0928\u093F\u092F\u0902\u0924\u094D\u0930\u0923 \u0915\u093E \u0938\u092C\u0938\u0947 \u092C\u0921\u093C\u093E \u0938\u093E\u0927\u0928 \u0939\u0948\u0964"',
  'summary.quote11': '"\u0938\u093E\u0901\u0938 \u0932\u0947\u0928\u093E \u091C\u0940\u0935\u0928 \u0915\u093E \u0938\u092C\u0938\u0947 \u092C\u0921\u093C\u093E \u0906\u0928\u0902\u0926 \u0939\u0948\u0964" \u2014 \u091C\u094B\u0935\u093E\u0928\u094D\u0928\u0940 \u092A\u093E\u092A\u093F\u0928\u0940',
  'summary.quote12': '"\u092E\u0941\u0938\u094D\u0915\u0941\u0930\u093E\u0907\u090F, \u0938\u093E\u0901\u0938 \u0932\u0947\u0902, \u0914\u0930 \u0927\u0940\u0930\u0947 \u091A\u0932\u0947\u0902\u0964" \u2014 \u0925\u093F\u091A \u0928\u094D\u0939\u093E\u0924 \u0939\u093E\u0928\u094D\u0939',
  'summary.quote13': '"\u091C\u0940\u0935\u0928 \u0907\u0938 \u092C\u093E\u0924 \u0938\u0947 \u0928\u0939\u0940\u0902 \u092E\u093E\u092A\u093E \u091C\u093E\u0924\u093E \u0915\u093F \u0939\u092E \u0915\u093F\u0924\u0928\u0940 \u0938\u093E\u0901\u0938\u0947\u0902 \u0932\u0947\u0924\u0947 \u0939\u0948\u0902, \u092C\u0932\u094D\u0915\u093F \u0909\u0928 \u092A\u0932\u094B\u0902 \u0938\u0947 \u091C\u094B \u0939\u092E\u093E\u0930\u0940 \u0938\u093E\u0901\u0938 \u0925\u093E\u092E \u0926\u0947\u0924\u0947 \u0939\u0948\u0902\u0964"',
